import json
with open('CoachForce.json') as f:
    data = json.load(f)

# Search for market research report documents
def search_dict(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'market' in str(k).lower() and 'research' in str(k).lower():
                print(f'FOUND KEY: {path}.{k}')
                print(json.dumps(v, indent=2)[:2000])
                print('---')
            if 'market_research' in str(k).lower():
                print(f'FOUND KEY: {path}.{k}')
                print(json.dumps(v, indent=2)[:2000])
                print('---')
            search_dict(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d):
            search_dict(item, f'{path}[{i}]')

search_dict(data)
